css:
body { font-family: system-ui, sans-serif; margin: 0; }
.topbar { background: #164f3b; color: white; padding: 0.5rem 1rem; position: sticky; top: 0; }
.card { border: 1px solid #ddd; border-radius: 8px; padding: 1rem; margin: 1rem; position: relative; max-width: 320px; }
.badge { background: #c62828; color: white; padding: 2px 8px; border-radius: 4px; position: absolute; top: 8px; right: 8px; }
.tag { background: #eee; padding: 4px 10px; border-radius: 99px; display: inline-block; height: 28px; }
.promo { display: none; }
